\midrule
\multirow{4}{*}{Qwen3-4B} & SFT & 39.74 & 79.86 & 0.698 & baseline \\
 & RSFT CED & 44.9 & 81.2 & 0.647 & none \\
 & GRPO bf16 & 45.5 & 80.9 & 0.632 & mild ($-$2pp) \\
